{
     "title": "CSCI-510: Introduction to Computer Graphics - Lesson Blueprint",
     "learningObjectives": [
       "Define the core components of the hardware rasterization pipeline and explain their sequential processing of geometric primitives.",
       "Apply coordinate transformations and projection matrices to map 3-D scene geometry into a 2-D image plane for rendering.",
       "Evaluate the impact of rasterization parameters, such as depth testing and blending, on visual correctness and performance in interactive graphics."
     ],
     "beats": [
       {
         "title": "Pipeline Overview",
         "claim": "The OpenGL graphics pipeline processes vertices through programmable shader stages before rasterization.",
         "example": "A vertex shader modifies position and color attributes for each triangle vertex before they reach the rasterizer.",
         "visualDirection": "Display a horizontal flowchart with labeled stages: Vertex Shader -> Geometry Shader -> Rasterizer -> Fragment Shader -> Framebuffer.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Primitive Assembly",
         "claim": "Primitive assembly groups vertices into points, lines, or triangles for downstream processing.",
         "example": "Three connected vertices form a triangle primitive that the rasterizer will convert into a set of pixel candidates.",
         "visualDirection": "Show a wireframe triangle with vertices labeled A, B, and C, highlighting the edges connecting them.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Clipping Process",
         "claim": "Clipping removes portions of primitives that fall outside the view volume before rasterization.",
         "example": "A large triangle extending beyond the camera's field of view is clipped to fit within the viewport boundaries.",
         "visualDirection": "Illustrate a triangle partially outside a rectangular viewport, with the clipped portion shaded in gray and the visible portion in white.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Rasterization Conversion",
         "claim": "Rasterization converts primitives into fragment candidates on a discrete pixel grid.",
         "example": "Each pixel within the clipped triangle receives a set of interpolated vertex attributes for processing.",
         "visualDirection": "Render a grid of pixels covering a triangle, with each pixel showing a small coordinate index and a dot representing the fragment candidate.",
         "sourceIds": ["khronos-opengl", "mit-computer-graphics"]
       },
       {
         "title": "Interpolation Mechanism",
         "claim": "Interpolation produces per-fragment values from vertex outputs using linear or perspective-correct methods.",
         "example": "Color and texture coordinates are calculated for each pixel based on the weighted average of the triangle's vertex attributes.",
         "visualDirection": "Draw a triangle with gradient shading across its surface, showing how values transition smoothly from vertex to vertex.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Fragment Processing",
         "claim": "Fragment processing computes values for framebuffer operations using shader programs.",
         "example": "A fragment shader applies a lighting model to each pixel, calculating final color based on material properties and light direction.",
         "visualDirection": "Show a side-by-side comparison of a wireframe triangle and a fully shaded triangle with computed colors.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Depth Testing & Visibility",
         "claim": "Depth testing resolves visibility according to stored depth values to handle overlapping geometry.",
         "example": "A closer triangle overwrites a farther triangle's pixels because its depth values are smaller than the stored depth buffer.",
         "visualDirection": "Illustrate two overlapping triangles with depth values displayed as numerical annotations, showing the closer one winning the test.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Blending Operations",
         "claim": "Blending combines a fragment result with an existing framebuffer value to achieve transparency effects.",
         "example": "A semi-transparent overlay triangle mixes its computed color with the background color using a specified alpha factor.",
         "visualDirection": "Display a background rectangle and a semi-transparent triangle on top, with a formula showing alpha blending calculation.",
         "sourceIds": ["khronos-opengl"]
       },
       {
         "title": "Coordinate Spaces & Projections",
         "claim": "Coordinate spaces, sampling, and numerical precision must remain explicit to maintain visual correctness.",
         "example": "Vertices are transformed from model space to clip space using a projection matrix before being converted to normalized device coordinates.",
         "visualDirection": "Show a diagram of three nested coordinate spaces (model, view, clip) with arrows indicating transformation flow.",
         "sourceIds": ["khronos-opengl", "mit-computer-graphics"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Durable concepts and problem-solving methods are reinforced by verifying pipeline stages, transformation accuracy, and rendering parameters.",
         "example": "Instructors verify that vertex attributes are correctly interpolated, depth buffers are updated, and blending modes match intended visual outcomes.",
         "visualDirection": "List a checklist with checkboxes for: 1. Shader stage execution order, 2. Coordinate transformation accuracy, 3. Depth and blending parameter validation.",
         "sourceIds": ["rit-csci-510"]
       }
     ]
   }
